  bool pick_reference_color_at(QPointF pos){
    const auto pane = pane_at(pos);
    if (!pane || pane->kind != bts::ViewKind::Uv || !reference_image_enabled || !reference_image.valid()) return false;
    const double scale = devicePixelRatioF();
    const QRectF rect(pane->x / scale, pane->y / scale, pane->width / scale, pane->height / scale);
    const auto uv = bts::reference_image_uv_at(rect, reference_image.width, reference_image.height, ref_center_, ref_vertical_extent_, pos);
    if (!uv) return false;
    const auto sample = bts::sample_reference_image_uv_rgba(reference_image, uv->x(), uv->y());
    if (!sample) return false;
    last_picked_color_ = *sample;
    if (reference_color_picked) reference_color_picked(*sample);
    update();
    return true;
  }
