  void detach_scene_camera(){if(!current_imported_camera_)return;last_imported_camera_=current_imported_camera_;camera_.release_scene_camera(scene_pane_size());current_imported_camera_.reset();{QSignalBlocker block(camera_selector_);camera_selector_->setCurrentIndex(0);}default_camera_=camera_;const int index=camera_selector_->findData(*last_imported_camera_);camera_back_->setText("Back to \""+camera_selector_->itemText(index)+"\" camera");camera_back_->show();camera_notice_->show();position_camera_controls();}
  void position_camera_controls(){bool visible=false;const double ratio=devicePixelRatioF();for(const auto &pane:panes())if(pane.kind==bts::ViewKind::Scene&&!scene_cameras_.empty()){visible=true;const int right=qRound((pane.x+pane.width)/ratio),top=qRound(pane.y/ratio),bottom=qRound((pane.y+pane.height)/ratio);camera_selector_->setGeometry(right-260,top+8,150,23);camera_back_->setGeometry(right-280,bottom-36,270,26);camera_notice_->setGeometry(right-280,bottom-59,270,22);}camera_selector_->setVisible(visible);if(!visible){camera_back_->hide();camera_notice_->hide();}}

