  void tabletEvent(QTabletEvent *event) override
  {
    bts::tablet::event(*event,tablet_contact_,tablet_dispatch_,input_pressure_);
    // Hover must not replace either a contacting pen or an active mouse stroke.
    // A deliberate press can transfer ownership; removal clears it separately.
    if(event->type()!=QEvent::TabletPress&&((tablet_contact_&&tablet_device_!=event->pointingDevice())||(painting_&&!tablet_contact_))){event->accept();return;}
    tablet_recent_.restart();
    if(!std::isfinite(event->pressure())){end_paint(true);tablet_contact_=false;event->accept();return;}
    if(event->pointerType()==QPointingDevice::PointerType::Eraser){end_paint(true);tablet_contact_=false;input_pressure_=0;pointer_name_="Eraser";update();event->accept();return;}
    if(tablet_device_!=event->pointingDevice()){
      if(tablet_contact_)cancel_tablet_contact();
      tablet_device_=event->pointingDevice();
      // Device pointers, rather than IDs, survive unplug/replug and ID reuse safely.
      connect(tablet_device_,&QObject::destroyed,this,[this](QObject *removed){if(tablet_device_.isNull()||tablet_device_.data()==removed)cancel_tablet_contact();});
    }
    pointer_name_="Pen: "+event->pointingDevice()->name();
    const bool press=event->type()==QEvent::TabletPress,release=event->type()==QEvent::TabletRelease;
    const bool tip=event->button()==Qt::LeftButton;
    // A master-pointer press can precede the matching TabletPress. Roll back
    // that provisional mouse stroke before its first full-pressure dab survives.
    if(press&&tip){if(painting_)end_paint(true);tablet_contact_=true;}
    // Pressure is independent of the buttons mask. In particular, a missing
    // LeftButton on a contact move must neither reset pressure nor cancel paint.
    if(!release){input_pressure_=float(std::clamp(event->pressure(),0.,1.));input_tilt_={std::clamp(double(event->xTilt()),-90.,90.),std::clamp(double(event->yTilt()),-90.,90.)};}
    const auto type=press?QEvent::MouseButtonPress:release?QEvent::MouseButtonRelease:QEvent::MouseMove;
    // Mutter applies stylus settings before XWayland maps BTN_STYLUS/2 to
    // XI buttons 2/3. Qt already reports Middle/Right; swapping here reverses
    // the user's system mapping. Preserve both the changed button and mask.
    auto buttons=event->buttons();if(tablet_contact_&&!release)buttons|=Qt::LeftButton;
    tablet_dispatch_=true;
    QMouseEvent translated(type,event->position(),event->globalPosition(),event->button(),buttons,event->modifiers(),event->pointingDevice());
    translated.setTimestamp(event->timestamp());
    if(press)mousePressEvent(&translated);else if(release)mouseReleaseEvent(&translated);else mouseMoveEvent(&translated);
    tablet_dispatch_=false;
    if(release&&tip){tablet_contact_=false;input_pressure_=0;}
    update();
    event->accept(); // Prevent Qt's unhandled-tablet fallback from synthesizing a second mouse stroke.
  }

