  parser.addOption({"headless-cycles-cuda-test", "Render the factory scene with Cycles CUDA and OptiX; fail on CPU fallback", "directory"});
  parser.addOption({"headless-viewport-test", "Exercise EEVEE and UDIM mips without a visible window", "directory"});
