  parser.addOption({"cpu-render-status-test", "Verify visible CUDA errors and CPU fallback without a GPU"});
  parser.addOption({"cpu-workspace-shutdown-test", "Verify pending nested editor retirement without initializing Blender or a viewport"});
  parser.addOption({"cpu-prepare-polyhaven", "Prepare one built-in CC0 material", "directory"});
  parser.addOption({"polyhaven-source", "Generated source materials", "directory"});
  parser.addOption({"cpu-native-material-test", "Inspect detached Blender material groups without a GPU", "directory"});
  parser.addOption({"cpu-bake-source-test", "Verify native OBJ/ABC/USD high-poly and cage import", "directory"});
  parser.addOption({"headless-surface-bake-test", "Verify displaced surface maps on an offscreen GPU", "directory"});
  parser.addOption({"cpu-skew-test", "Run native high-to-low skew ray projection without a GPU", "directory"});
  parser.addOption({"cpu-texture-import-test", "Verify native image formats, raw/color UDIM decode and per-tile packing", "directory"});
  parser.addOption({"cpu-export-test", "Run headless native image export regression without a GPU", "directory"});
  parser.process(app);
  if (parser.isSet("gui-fix-resolution")) {
    bool okay=false;
    const int size=parser.value("gui-fix-resolution").toInt(&okay);
    if (!okay || size<128 || size>bts::max_texture_resolution || (size&(size-1))) {
      qCritical("--gui-fix-resolution must be a power of two from 128 to 8192 (8K)");
      return 2;
    }
  }
  if(parser.isSet("brush-presets-demo")){if(parser.isSet("gui-fix-demo")||parser.isSet("material-layering-demo")){qCritical("Choose one diagnostic actor");return 2;}qputenv("BTS_BO_PRESET_DEMO",parser.value("brush-presets-demo").toUtf8());}
  if(parser.isSet("material-layering-demo")&&parser.isSet("gui-fix-demo")){qCritical("Choose one diagnostic actor");return 2;}
  if(parser.isSet("cpu-asset-dragdrop-test"))return bts::run_asset_workspace_drop_test(parser.value("cpu-asset-dragdrop-test"));
