                auto point=viewport->uv_point({.3,.5});send_drag(*viewport,point,{0,0},Qt::LeftButton,Qt::NoModifier);brush.stroke_opacity=50;point=viewport->uv_point({.55,.5});send_drag(*viewport,point,{0,0},Qt::LeftButton,Qt::NoModifier);brush.stroke_opacity=100;brush.values.roughness=.1;select_material(selected_material);
